macro_rules! test_cleanup_semantic_lossless {
    () => {
        # [test] fn test_cleanup_semantic_lossless () { let mut solution = diff_list ! [] ; cleanup_semantic_lossless (& mut solution) ; assert_diffs ! ([] , solution , "Null case") ; let mut solution = diff_list ! [Equal ("AAA\r\n\r\nBBB") , Insert ("\r\nDDD\r\n\r\nBBB") , Equal ("\r\nEEE") ,] ; cleanup_semantic_lossless (& mut solution) ; assert_diffs ! ([Equal ("AAA\r\n\r\n") , Insert ("BBB\r\nDDD\r\n\r\n") , Equal ("BBB\r\nEEE") ,] , solution , "Blank lines" ,) ; let mut solution = diff_list ! [Equal ("AAA\r\nBBB") , Insert (" DDD\r\nBBB") , Equal (" EEE")] ; cleanup_semantic_lossless (& mut solution) ; assert_diffs ! ([Equal ("AAA\r\n") , Insert ("BBB DDD\r\n") , Equal ("BBB EEE")] , solution , "Line boundaries" ,) ; let mut solution = diff_list ! [Equal ("The c") , Insert ("ow and the c") , Equal ("at.")] ; cleanup_semantic_lossless (& mut solution) ; assert_diffs ! ([Equal ("The ") , Insert ("cow and the ") , Equal ("cat.")] , solution , "Word boundaries" ,) ; let mut solution = diff_list ! [Equal ("The-c") , Insert ("ow-and-the-c") , Equal ("at.")] ; cleanup_semantic_lossless (& mut solution) ; assert_diffs ! ([Equal ("The-") , Insert ("cow-and-the-") , Equal ("cat.")] , solution , "Alphanumeric boundaries" ,) ; let mut solution = diff_list ! [Equal ("a") , Delete ("a") , Equal ("ax")] ; cleanup_semantic_lossless (& mut solution) ; assert_diffs ! ([Delete ("a") , Equal ("aax")] , solution , "Hitting the start") ; let mut solution = diff_list ! [Equal ("xa") , Delete ("a") , Equal ("a")] ; cleanup_semantic_lossless (& mut solution) ; assert_diffs ! ([Equal ("xaa") , Delete ("a")] , solution , "Hitting the end") ; let mut solution = diff_list ! [Equal ("The xxx. The ") , Insert ("zzz. The ") , Equal ("yyy.")] ; cleanup_semantic_lossless (& mut solution) ; assert_diffs ! ([Equal ("The xxx.") , Insert (" The zzz.") , Equal (" The yyy.")] , solution , "Sentence boundaries" ,) ; }
    };
}

test_cleanup_semantic_lossless!();